local BookSpineRulerMaker = {}
local PRODUCTS = {
    iron_bookspineruler = { name = "Železni merilnik hrbtov", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni merilnik hrbtov za knjigoveze." },
    bronze_bookspineruler = { name = "Bronast merilnik hrbtov", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast merilnik hrbtov za knjigoveze." },
    silver_bookspineruler = { name = "Srebrn merilnik hrbtov", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn merilnik hrbtov za knjigoveze." },
    gilded_bookspineruler = { name = "Pozlačen merilnik hrbtov", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen merilnik hrbtov za knjigoveze." },
    jewel_set_bookspineruler = { name = "Draguljast merilnik hrbtov", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast merilnik hrbtov za knjigoveze." },
    royal_sovereign_bookspineruler = { name = "Kraljevski suveren merilnik hrbtov", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren merilnik hrbtov z biseri za krono." },
}
local BUILDINGS = {
    bookspineruler_workshop = { name = "Bookspineruler delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    bookspineruler_house = { name = "Bookspineruler hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_bookspineruler_atelier = { name = "Mojstrski bookspineruler atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_bookspineruler_palace = { name = "Suverena bookspineruler palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
BookSpineRulerMaker.ironStock=12; BookSpineRulerMaker.bronzeStock=10; BookSpineRulerMaker.woodStock=16; BookSpineRulerMaker.leatherStock=10; BookSpineRulerMaker.silverStock=8; BookSpineRulerMaker.goldStock=6; BookSpineRulerMaker.jewelStock=4; BookSpineRulerMaker.pearlStock=4
BookSpineRulerMaker.productStock = {}; BookSpineRulerMaker.buildings = {}; BookSpineRulerMaker.maker = nil; BookSpineRulerMaker.activeMaking = {}; BookSpineRulerMaker.totalProducts = 0; BookSpineRulerMaker.dayTimer = 0
function BookSpineRulerMaker.init() BookSpineRulerMaker.ironStock=12; BookSpineRulerMaker.bronzeStock=10; BookSpineRulerMaker.woodStock=16; BookSpineRulerMaker.leatherStock=10; BookSpineRulerMaker.silverStock=8; BookSpineRulerMaker.goldStock=6; BookSpineRulerMaker.jewelStock=4; BookSpineRulerMaker.pearlStock=4; BookSpineRulerMaker.productStock={}; BookSpineRulerMaker.buildings={}; BookSpineRulerMaker.maker=nil; BookSpineRulerMaker.activeMaking={}; BookSpineRulerMaker.totalProducts=0; BookSpineRulerMaker.dayTimer=0; print("[BookSpineRulerMaker] Royal Book Spine Ruler Maker System initialized (6 products, 4 buildings)") end
function BookSpineRulerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BookSpineRulerMaker.maker={name=n or ("Merilnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Merilnik najet: %s (spretnost: %d)",BookSpineRulerMaker.maker.name,s),"success") end; return true end
function BookSpineRulerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BookSpineRulerMaker.build(id) local ok,e=BookSpineRulerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BookSpineRulerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BookSpineRulerMaker.getQualityBonus() local b=0; for _,bd in ipairs(BookSpineRulerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BookSpineRulerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BookSpineRulerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BookSpineRulerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BookSpineRulerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BookSpineRulerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BookSpineRulerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BookSpineRulerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BookSpineRulerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BookSpineRulerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BookSpineRulerMaker.buildings==0 then return false,"Potrebna merilna delavnica" end; if not BookSpineRulerMaker.maker then return false,"Potreben merilnik" end; return true end
function BookSpineRulerMaker.make(pt,qty) qty=qty or 1; local ok,e=BookSpineRulerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BookSpineRulerMaker.ironStock=BookSpineRulerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BookSpineRulerMaker.bronzeStock=BookSpineRulerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BookSpineRulerMaker.woodStock=BookSpineRulerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BookSpineRulerMaker.leatherStock=BookSpineRulerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BookSpineRulerMaker.silverStock=BookSpineRulerMaker.silverStock-d.silverCost*qty end; if d.goldCost then BookSpineRulerMaker.goldStock=BookSpineRulerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BookSpineRulerMaker.jewelStock=BookSpineRulerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BookSpineRulerMaker.pearlStock=BookSpineRulerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BookSpineRulerMaker.maker then t=math.max(1,t-math.floor(BookSpineRulerMaker.maker.skill/13)) end; table.insert(BookSpineRulerMaker.activeMaking,{id="bookspineruler_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BookSpineRulerMaker.completeMaking(m) local q=1.0+(BookSpineRulerMaker.getQualityBonus()/100); if BookSpineRulerMaker.maker then q=q+(BookSpineRulerMaker.maker.skill/140) end; q=math.min(2.5,q); BookSpineRulerMaker.productStock[m.productType]=(BookSpineRulerMaker.productStock[m.productType] or 0)+m.quantity; BookSpineRulerMaker.totalProducts=BookSpineRulerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BookSpineRulerMaker.maker then BookSpineRulerMaker.maker.itemsMade=BookSpineRulerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BookSpineRulerMaker.maker.skill=math.min(100,BookSpineRulerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Merilnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bookspineruler.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BookSpineRulerMaker.update(dt) if not _G.state then return end; BookSpineRulerMaker.dayTimer=BookSpineRulerMaker.dayTimer+dt; if BookSpineRulerMaker.dayTimer>=30 then BookSpineRulerMaker.dayTimer=0; for i=#BookSpineRulerMaker.activeMaking,1,-1 do local m=BookSpineRulerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BookSpineRulerMaker.completeMaking(m); table.remove(BookSpineRulerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BookSpineRulerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BookSpineRulerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BookSpineRulerMaker.getStats() return {ironStock=BookSpineRulerMaker.ironStock,bronzeStock=BookSpineRulerMaker.bronzeStock,woodStock=BookSpineRulerMaker.woodStock,leatherStock=BookSpineRulerMaker.leatherStock,silverStock=BookSpineRulerMaker.silverStock,goldStock=BookSpineRulerMaker.goldStock,jewelStock=BookSpineRulerMaker.jewelStock,pearlStock=BookSpineRulerMaker.pearlStock,productStock=BookSpineRulerMaker.productStock,numBuildings=#BookSpineRulerMaker.buildings,hasMaker=BookSpineRulerMaker.maker~=nil,makerName=BookSpineRulerMaker.maker and BookSpineRulerMaker.maker.name or "—",makerSkill=BookSpineRulerMaker.maker and BookSpineRulerMaker.maker.skill or 0,activeMaking=#BookSpineRulerMaker.activeMaking,totalProducts=BookSpineRulerMaker.totalProducts} end
return BookSpineRulerMaker
